@startuml

class GasStation {
  + ID : int
  + Address : string
}

class FuelPump {
  + PumpNumber : int
  + IsSelfService : boolean
}

class Fuel {
  + Name : string
  + OctaneRating : int
}

class DailyPrice {
  + Date : date
  + PricePerLiter : double
}

class FuelPurchase {
  + PurchaseID : int
  + LitersDispensed : double
}

GasStation "1" *-- "1..12" FuelPump
GasStation "1" -- "*" DailyPrice
FuelPump "1" -- "*" Fuel
Fuel "1" -- "*" DailyPrice
FuelPump "1" -- "*" FuelPurchase
DailyPrice "1" -- "*" FuelPurchase

@enduml

